152:     /**
153:      * Receive history data from qute://history/data.
154:      *
155:      * @param {Number} status - The status of the query.
156:      * @param {Array} history - History data.
157:      * @returns {void}
158:      */
159:     function receiveHistory(status, history) {
160:         if (history === null) {
161:             return;
162:         }
163: 
164:         if (history.length === 0) {
165:             // Reached end of history
166:             window.onscroll = null;
167:             EOF_MESSAGE.style.display = "block";
168:             LOAD_LINK.style.display = "none";
169:             return;
170:         }
171: 
172:         nextTime = history[history.length - 1].time;
173:         nextOffset = 0;
174: 
175:         for (var i = 0, len = history.length; i < len; i++) {
176:             var item = history[i];
177:             // python's time.time returns seconds, but js Date expects ms
178:             var currentItemDate = new Date(item.time * 1000);
179:             getSessionNode(currentItemDate).appendChild(makeHistoryRow(
180:                 item.url, item.title, currentItemDate.toLocaleTimeString()
181:             ));
182:             lastItemDate = currentItemDate;
183:             if (item.time === nextTime) {
184:                 nextOffset++;
185:             }
186:         }
187:     }
